window.HOEREN_TESTS[5] = {"id":"beim-arzt-und-in-der-apotheke","name":"Beim Arzt und in der Apotheke","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, Frau Klein. Hier ist die Praxis Dr. Bauer. Ihr Termin morgen um 14 Uhr fällt leider aus — Doktor Bauer ist überraschend krank. Wir können Ihnen aber Donnerstag um 10 Uhr oder Freitag um 16 Uhr anbieten. Bitte rufen Sie zurück, um zu bestätigen. Vielen Dank für Ihr Verständnis.","gender":"f","q":"Wann ist der neue Termin möglich?","opts":["Morgen um 14 Uhr wie geplant.","Erst nächste Woche.","Donnerstag oder Freitag."],"correct":2},{"transcript":"Liebe Patienten, die Apotheke hat heute Notdienst bis 22 Uhr. Wir haben alle Medikamente vorrätig, außer ein bestimmtes Schmerzmittel — das ist erst Mittwoch wieder da. Bitte kommen Sie mit dem Rezept, sonst können wir nicht abgeben. Auch ohne Rezept bieten wir Ihnen gern eine Beratung an, das ist immer kostenlos.","gender":"m","q":"Was ist heute nicht verfügbar?","opts":["Notdienst.","Die Beratung.","Ein bestimmtes Schmerzmittel."],"correct":2},{"transcript":"Hallo Schatz, hier ist Mama. Du musst heute zur Apotheke gehen für mein Medikament — Insulin, du weißt schon. Das Rezept liegt auf dem Küchentisch. Auch noch Vitamin C-Tabletten, weil ich erkältet bin. Und falls möglich Hustensaft. Aber wenn die Apotheke schon zu hat, kommt das alles bis morgen früh.","gender":"f","q":"Was ist am wichtigsten zu holen?","opts":["Vitamin C-Tabletten.","Insulin.","Hustensaft."],"correct":1},{"transcript":"Krankenhaus-Information für alle Besucher. Die Besuchszeit dauert bis 19 Uhr. Bitte bringen Sie keine Blumen mit — wegen Allergien sind die in unserem Haus verboten. Kuchen und Obst sind erlaubt, aber bitte fragen Sie vorher die Pflege, ob der Patient das essen darf. Vielen Dank. Gute Besserung!","gender":"f","q":"Was ist im Krankenhaus verboten?","opts":["Blumen mitbringen.","Kuchen mitbringen.","Obst essen."],"correct":0},{"transcript":"Hallo Tom, hier ist Maria von der Massage-Praxis. Du, dein Termin am Freitag — der Therapeut Robert ist plötzlich im Urlaub. Eine Kollegin, Frau Lehmann, kann dich aber stattdessen behandeln. Sie ist sehr erfahren, sogar besser als Robert würde ich sagen. Wenn das okay ist, bleibt der Termin. Sonst verschieben wir.","gender":"f","q":"Was hat sich geändert?","opts":["Der Therapeut.","Der Tag des Termins.","Der Preis."],"correct":0}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Nina","gender":"f","text":"Hallo Paul! Das Wellness-Hotel hat diese Woche noch freie Termine für uns."},{"speaker":"Paul","gender":"m","text":"Ich bin froh, dass du anrufst. An einem einzigen Tag ist das zu viel."},{"speaker":"Nina","gender":"f","text":"Eine Rückenmassage lasse ich am Montag machen. Seit Tagen tut mir der Rücken weh."},{"speaker":"Paul","gender":"m","text":"Eva wollte eigentlich zum Friseur gehen. Schaffen wir das noch?"},{"speaker":"Nina","gender":"f","text":"Nein. Zum Friseur geht sie diese Woche nicht. Die Haare schneidet sie später zu Hause."},{"speaker":"Paul","gender":"m","text":"Ich gehe am Dienstag lange in die Sauna. Danach habe ich den ganzen Nachmittag frei."},{"speaker":"Nina","gender":"f","text":"Die Wärme tut dir sicher gut. Wollen wir an einem Morgen auch schwimmen?"},{"speaker":"Paul","gender":"m","text":"Nein. Wir gehen nicht schwimmen. Das Becken bleibt wegen der Reparatur zu."},{"speaker":"Nina","gender":"f","text":"Eva bucht am Mittwoch eine Gesichtsbehandlung. Ihre Haut ist sehr trocken."},{"speaker":"Paul","gender":"m","text":"Das passt gut zu ihr. Robert sucht noch einen ruhigen Kurs."},{"speaker":"Nina","gender":"f","text":"Robert macht am Donnerstag Yoga im hellen Kursraum."},{"speaker":"Paul","gender":"m","text":"Sollen wir auch noch Akupunktur buchen?"},{"speaker":"Nina","gender":"f","text":"Nein. Akupunktur steht bei uns nicht auf dem Zettel. Davor habe ich wirklich Angst."},{"speaker":"Paul","gender":"m","text":"Lisa lässt am Freitag eine Maniküre machen. Ihre Nägel sollen zum Fest hübsch aussehen."},{"speaker":"Nina","gender":"f","text":"Einverstanden. Ich hänge den Plan an den Kühlschrank."},{"speaker":"Paul","gender":"m","text":"Dann sehen wir uns morgen früh zum ersten Termin."}],"options":[{"letter":"a","text":"bekommt eine Akupunktur"},{"letter":"b","text":"geht zum Friseur"},{"letter":"c","text":"geht in die Sauna"},{"letter":"d","text":"geht schwimmen"},{"letter":"e","text":"lässt eine Rückenmassage machen"},{"letter":"f","text":"bucht eine Gesichtsbehandlung"},{"letter":"g","text":"macht Yoga"},{"letter":"h","text":"macht eine Fußmassage"},{"letter":"i","text":"lässt eine Maniküre machen"}],"items":[{"person":"Montag","correct":"e"},{"person":"Dienstag","correct":"c"},{"person":"Mittwoch","correct":"f"},{"person":"Donnerstag","correct":"g"},{"person":"Freitag","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Arzt","gender":"m","text":"Was tut weh?"},{"speaker":"Patient","gender":"m","text":"Mein Hals. Und ich habe Husten. Der Magen ist okay."},{"speaker":"Arzt","gender":"m","text":"Fieber auch?"},{"speaker":"Patient","gender":"m","text":"Nein, kein Fieber. Aber starker Husten, vor allem nachts."},{"speaker":"Arzt","gender":"m","text":"Ich verschreibe Ihnen einen Hustensaft. Trinken Sie viel warmen Tee, das hilft auch. Und bleiben Sie zwei Tage im Bett. Viel Wasser trinken!"}],"q":"Welches Problem hat der Patient?","opts":["Fieber.","Halsschmerzen und Husten.","Magenschmerzen."],"correct":1},{"lines":[{"speaker":"Apothekerin","gender":"f","text":"Sie haben das Rezept dabei, oder?"},{"speaker":"Kunde","gender":"m","text":"Ja, hier. Aber kostet das viel?"},{"speaker":"Apothekerin","gender":"f","text":"Mit Rezept zahlen Sie nur 5 Euro Eigenanteil. Ohne Rezept wären es 28 Euro."},{"speaker":"Kunde","gender":"m","text":"Gut, dass ich das Rezept dabei habe. 23 Euro wären zu viel."},{"speaker":"Apothekerin","gender":"f","text":"Genau, hier sind die Medikamente. Gute Besserung!"},{"speaker":"Kunde","gender":"m","text":"Danke! Tschüss und schönen Tag!"}],"q":"Was zahlt der Kunde?","opts":["5 Euro.","23 Euro.","28 Euro."],"correct":0},{"lines":[{"speaker":"Patientin","gender":"f","text":"Ich möchte einen Termin für meinen Sohn."},{"speaker":"Arzthelferin","gender":"f","text":"Was hat er denn?"},{"speaker":"Patientin","gender":"f","text":"Er hat sich am Bein verletzt beim Fußball."},{"speaker":"Arzthelferin","gender":"f","text":"Wir haben heute um 11 Uhr noch frei, oder morgen um 9. Heute ist besser für eine Sportverletzung. Nächste Woche wäre zu spät."},{"speaker":"Patientin","gender":"f","text":"Dann heute um 11. Danke, bis später!"}],"q":"Wann ist der Termin?","opts":["Heute um 11 Uhr.","Morgen um 9 Uhr.","Erst nächste Woche."],"correct":0},{"lines":[{"speaker":"Krankenschwester","gender":"f","text":"Sie kommen zur Untersuchung, ja? Zur Blutuntersuchung?"},{"speaker":"Patient","gender":"m","text":"Ja, eine Blutuntersuchung."},{"speaker":"Krankenschwester","gender":"f","text":"Sie sind nüchtern, hoffe ich?"},{"speaker":"Patient","gender":"m","text":"Ich habe heute Morgen einen Kaffee getrunken. Keinen Tee und kein Wasser, nur Kaffee."},{"speaker":"Krankenschwester","gender":"f","text":"Hmm, eigentlich auch kein Kaffee. Aber meistens geht das, wir machen es trotzdem. Keine Sorge, das geht schnell."}],"q":"Was hat der Patient heute Morgen getrunken?","opts":["Wasser.","Tee.","Kaffee."],"correct":2},{"lines":[{"speaker":"Kollegin","gender":"f","text":"Ich brauche ein Aspirin. Hast du eins? Oder ein Glas Wasser?"},{"speaker":"Kollege","gender":"m","text":"Kopfschmerzen? Seit wann?"},{"speaker":"Kollegin","gender":"f","text":"Schrecklich. Schon seit heute Morgen, es wird schlimmer."},{"speaker":"Kollege","gender":"m","text":"Aspirin habe ich nicht, aber Paracetamol. Hilft auch gut."},{"speaker":"Kollegin","gender":"f","text":"Gib her, danke! Wasser hole ich mir selbst."},{"speaker":"Kollege","gender":"m","text":"Hier, Paracetamol. Gute Besserung, ruh dich aus!"}],"q":"Was bekommt die Kollegin?","opts":["Aspirin.","Paracetamol.","Wasser."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Doktor Weber, einer Allgemeinärztin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Doktor Weber, Sie haben Ihre eigene Praxis seit 12 Jahren. Wie sind Sie Ärztin geworden?"},{"speaker":"Weber","gender":"f","text":"Schon als Kind wollte ich Tierärztin werden — ich liebte Tiere. Aber während des Medizinstudiums habe ich gemerkt, dass mir der Kontakt mit Menschen viel mehr gibt. So bin ich Allgemeinärztin geworden."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihr typischer Arbeitstag?"},{"speaker":"Weber","gender":"f","text":"Ich beginne um 8 Uhr morgens, höre um 18 Uhr auf. Mittwochnachmittag mache ich Hausbesuche bei älteren Patienten, die nicht selbst kommen können. Das ist mir wichtig."},{"speaker":"Reporter","gender":"m","text":"Hat sich die Medizin seit Ihrem Studium verändert?"},{"speaker":"Weber","gender":"f","text":"Sehr, die Technik ist viel besser geworden. Aber das Wichtigste ist immer noch das Gespräch mit dem Patienten. Manche junge Ärzte vergessen das und schauen nur auf den Computer."},{"speaker":"Reporter","gender":"m","text":"Was ist das schwierigste an Ihrem Beruf?"},{"speaker":"Weber","gender":"f","text":"Schlechte Nachrichten geben. Das wird mit der Zeit nicht leichter. Im Gegenteil — ich finde es schwieriger als am Anfang."},{"speaker":"Reporter","gender":"m","text":"Und was machen Sie in Ihrer Freizeit?"},{"speaker":"Weber","gender":"f","text":"Ich gehe gern in die Natur, fahre Fahrrad, mache Yoga. Krimis lese ich auch sehr gern. Was ich nicht mache: Arztserien im Fernsehen schauen. Das reicht mir am Tag."}],"items":[{"q":"Sie macht Hausbesuche bei älteren Patienten.","correct":"ja"},{"q":"Als Kind wollte sie Ärztin werden.","correct":"nein"},{"q":"Das Gespräch mit dem Patienten ist heute weniger wichtig.","correct":"nein"},{"q":"Schlechte Nachrichten geben wird mit der Zeit leichter.","correct":"nein"},{"q":"Sie schaut gern Arztserien im Fernsehen.","correct":"nein"}]}]};
